import React, { useState } from 'react';
import API from '../api/axios';

const PostAnnouncement = () => {
  const [formData, setFormData] = useState({ title: '', description: '' });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await API.post('/admin/announcement', formData);
      alert('Announcement published successfully!');
      setFormData({ title: '', description: '' });
    } catch (err) {
      alert('Failed to publish announcement.');
    }
  };

  return (
    <div className="max-w-2xl mx-auto px-4 py-8">
      <div className="bg-white p-8 rounded-xl shadow border">
        <h2 className="text-2xl font-bold mb-6 text-slate-900">Publish Campus Announcement</h2>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="text-sm font-semibold text-slate-700">Notice Title</label>
            <input
              type="text" required placeholder="e.g. Campus Closed for Holiday"
              className="w-full mt-1 p-2 border rounded-md"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            />
          </div>

          <div>
            <label className="text-sm font-semibold text-slate-700">Notice Body / Description</label>
            <textarea
              required rows="5" placeholder="Write announcement details..."
              className="w-full mt-1 p-2 border rounded-md"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
          </div>

          <button type="submit" className="w-full bg-sky-600 hover:bg-sky-700 text-white font-bold py-2.5 rounded-lg transition">
            Publish Notice
          </button>
        </form>
      </div>
    </div>
  );
};

export default PostAnnouncement;
